def to_sd(obj):
    if hasattr(obj, "state_dict"):
        return dict(obj.state_dict())
    if isinstance(obj, dict):
        for k in ("state_dict", "model_state_dict", "model", "weights", "params"):
            v = obj.get(k)
            if hasattr(v, "state_dict"): return dict(v.state_dict())
            if isinstance(v, dict):      return dict(v)
        if obj and all(torch.is_tensor(t) for t in obj.values()):
            return dict(obj)
    raise TypeError(f"cannot interpret {type(obj)}")

def load_any(p):
    if p.suffix == ".safetensors":
        from safetensors.torch import load_file
        return load_file(str(p))
    return to_sd(torch.load(str(p), map_location="cpu", weights_only=False))

