BAR = "=" * 72

def load(p):
    with np.load(p, allow_pickle=False) as z:
        return {k: np.array(z[k], np.float64) for k in z.files}

def sha(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for c in iter(lambda: f.read(1 << 20), b""):
            h.update(c)
    return h.hexdigest()[:16]

# ---------- 1. is the network shared across model variants? ----------
print(BAR); print("1  network identity across variants"); print(BAR)
groups = {}
for p in sorted(RES.rglob("work/blocks.npz")):
    model, run = p.parents[2].name, p.parents[1].name
    groups.setdefault(run.rsplit("_", 1)[0], {}).setdefault(sha(p), set()).add(model)
for corpus, hs in sorted(groups.items()):
    for h, models in hs.items():
        print(f"  {corpus:8s} {h}  {len(models):2d} model(s)  {sorted(models)}")

truth = {}
for p in sorted(RES.rglob("parsed.json")):
    j = json.loads(p.read_text())
    truth.setdefault(j["corpus"], set()).update(j.get("copy_truth") or [])
print("\n  truth " + "   ".join(f"{c}={sorted(v)}" for c, v in sorted(truth.items())))

# ---------- 2. per-head metrics, raw and gauge-invariant ----------
def metrics(b, L, h):
    sl = slice(h * HD, (h + 1) * HD)
    Wq, Wk, Wv = b[f"W_q.{L}"][sl], b[f"W_k.{L}"][sl], b[f"W_v.{L}"][sl]
    Wo = b[f"W_o.{L}"][:, sl]
    s1, b1 = b[f"ln1_w.{L}"], b[f"ln1_b.{L}"]
    Aq = np.hstack([Wq * s1, (Wq @ b1)[:, None]])      # (64,385)
    Ak = np.hstack([Wk * s1, (Wk @ b1)[:, None]])
    Av = np.hstack([Wv * s1, (Wv @ b1)[:, None]])
    QK,  OV  = Wq.T @ Wk, Wo @ Wv                      # (384,384)
    QKi, OVi = Aq.T @ Ak, Wo @ Av                      # (385,385), (384,385)
    OVl      = Wo @ (Wv * s1)                          # (384,384), invariant linear part
    t = lambda X: abs(float(np.trace(X)))
    nQK, nOV, nQKi, nOVi, nOVl = map(np.linalg.norm, (QK, OV, QKi, OVi, OVl))
    return {
        "qk_k":       t(QK) ** 2 / nQK ** 2   if nQK   else 0.0,
        "qk_k_inv":   t(QKi) ** 2 / nQKi ** 2 if nQKi  else 0.0,
        "cos_qk":     t(QK) / (np.linalg.norm(Wq) * np.linalg.norm(Wk) + 1e-300),
        "cos_qk_inv": float((Aq * Ak).sum()) / (np.linalg.norm(Aq) * np.linalg.norm(Ak) + 1e-300),
        "ov_k":       t(OV) ** 2 / nOV ** 2   if nOV   else 0.0,
        "ov_k_inv":   t(OVl) ** 2 / nOVi ** 2 if nOVi  else 0.0,
        "align":      float((QK * OV).sum()) / (nQK * nOV + 1e-300),
        "norm_all":   float(np.sqrt(sum(np.linalg.norm(X) ** 2 for X in (Wq, Wk, Wv, Wo)))),
    }

LABS = {L: [f"L{L}H{h}" for h in range(NH)] for L in range(NL)}
HEAD = [f"L{L}H{h}" for L in range(NL) for h in range(NH)]

