print(BAR); print("3  truth ranks WITHIN its own layer (1 = highest in that layer)"); print(BAR)
METRICS = list(next(iter(next(iter(M.values())).values())).keys())
RANKS = {}
for metric in METRICS:
    RANKS[metric] = {}
    for corpus, mm in M.items():
        RANKS[metric][corpus] = {}
        for L in range(NL):
            v = np.array([mm[l][metric] for l in LABS[L]])
            o = np.argsort(-v, kind="mergesort")
            r = np.empty(NH); r[o] = np.arange(1, NH + 1)
            for i, l in enumerate(LABS[L]):
                RANKS[metric][corpus][l] = int(r[i])

def null_dist(metric):
    cells, ks = [], []
    for corpus in M:
        for L in range(NL):
            ts = [h for h in LABS[L] if h in truth.get(corpus, set())]
            if ts:
                cells.append([RANKS[metric][corpus][l] for l in LABS[L]])
                ks.append(len(ts))
    dist = Counter({0: 1})
    for r, k in zip(cells, ks):
        opts = Counter(sum(c) for c in combinations(r, k))
        nxt = Counter()
        for s0, c0 in dist.items():
            for s1, c1 in opts.items():
                nxt[s0 + s1] += c0 * c1
        dist = nxt
    n = sum(dist.values())
    return {s: c / n for s, c in dist.items()}

print(f"\n  {'metric':11s}  observed                                        sum  p(exact)")
for metric in METRICS:
    parts, tot = [], 0
    for corpus in M:
        for L in range(NL):
            for l in LABS[L]:
                if l in truth.get(corpus, set()):
                    rk = RANKS[metric][corpus][l]
                    tot += rk
                    parts.append(f"{corpus[:3]}:{l}={rk}")
    nd = null_dist(metric)
    p = sum(v for s, v in nd.items() if s <= tot)
    flag = "  <-- " if p < 0.01 else ""
    print(f"  {metric:11s}  {'  '.join(parts):48s} {tot:4d}  {p:.4f}{flag}")

# ---------- 5. is the metric just a norm proxy? ----------
print(BAR); print("4  within-layer Spearman vs head scale (norm proxy check)"); print(BAR)
def spear(a, b):
    a, b = np.asarray(a, float), np.asarray(b, float)
    ar = np.argsort(np.argsort(a, kind="mergesort"), kind="mergesort").astype(float)
    br = np.argsort(np.argsort(b, kind="mergesort"), kind="mergesort").astype(float)
    ar -= ar.mean(); br -= br.mean()
    d = np.linalg.norm(ar) * np.linalg.norm(br)
    return float(ar @ br / d) if d else 0.0

for metric in METRICS:
    rs = []
    for corpus, mm in M.items():
        for L in range(NL):
            v = [mm[l][metric] for l in LABS[L]]
            n = [mm[l]["norm_all"] for l in LABS[L]]
            rs.append(spear(v, n))
    print(f"  {metric:11s} mean rho vs norm_all = {np.mean(rs):+.3f}")

# ---------- 6. top-1 within layer, per network ----------
print(BAR); print("5  does the metric put a truth head top-1 in its layer?"); print(BAR)
for metric in METRICS:
    hits, cells = 0, 0
    for corpus in M:
